  pg('track', { t: 'Track', d: 'Public token tracking (stage and time only)' }, () => { EYN = 0; const t = M.ui.track || (F.mine() || {}).token || 'MCCI-2026-10482'; const a = F.app(t), v = db().svcs.find((x) => x.token === t); const res = a ? `<h3>Membership application</h3><p class="muted">${esc(t)}</p>${M.steps8(a)}<p style="margin-top:12px">${bd(a.stage === 'temp' ? 'Temporary' : M.STAGE_LABEL[a.stage])}</p>` : v ? `<h3>${M.sv(v.svc).n}</h3><p class="muted">${esc(t)} · submitted ${M.dt(v.submitted)}</p><br>${v.status === 'Issued' ? bd('Issued') : M.cd(v.due) + '<br>' + bd(v.status)}` : `<p class="muted">No token found.</p>`; return { title: 'Track', raw: pageH('Track a Token', 'See the stage of any application. No personal data is shown.') + sec('Status', 'Enter your token.', `<div class="card" style="max-width:900px;margin:auto"><div class="ask" style="border:1px solid var(--b)"><input id="tk" value="${esc(t)}" data-enter="#tkb"><button class="btn p" id="tkb" ${M.da('track.go', 'tk')}>Track</button></div><div style="margin-top:18px">${res}</div></div>`) + sec('Live board', 'Token, service, status and time only.', `<div class="card">${live()}</div>`, 'alt') }; });
  pg('live', { t: 'Live board', d: 'Lobby-screen board of chamber activity (anonymised)' }, () => { EYN = 0; return { title: 'Live board', raw: pageH('Live Board', 'Everything happening at the Chamber, anonymised. Built for the lobby screen too.') + sec('Chamber activity', 'Demo data.', `<div class="g4" style="margin-bottom:20px">${[[db().svcs.filter((v) => v.status === 'Issued').length, 'Services issued'], [db().apps.filter((a) => a.stage === 'temp').length, 'Temporary members'], [db().apps.filter((a) => a.stage === 'permanent').length, 'Converted to permanent'], [db().svcs.filter((v) => v.status !== 'Issued').length, 'In progress']].map((x) => `<div class="card st"><b style="font-size:30px">${x[0]}</b><small style="display:block" class="muted">${x[1]}</small></div>`).join('')}</div><div class="card"><div class="ch"><h3>Live feed</h3><span class="live">LIVE</span></div>${live()}</div>`) }; });
  pg('news', { t: 'News & Events', d: 'News posts and events calendar' }, () => { EYN = 0; return { title: 'News', raw: pageH('News & Events', 'Announcements, workshops and delegations.') + sec('Latest news', '', `<div class="g3">${db().posts.filter((p) => p.status === 'Live').map((p) => `<button class="sc" ${M.da('post.view', p.id)}><i style="background:#1b4f9c22">${ic('award', C.CB, 28)}</i><h4>${esc(p.title)}</h4><p>${esc(p.body)}</p>${bd(p.type)}</button>`).join('')}</div>`) + sec('Upcoming events', '', `<div class="g2" style="grid-template-columns:1.5fr 1fr"><div class="card">${M.calendar()}</div>${M.lst('Events', db().events.filter((e) => e.status === 'Open').map((e) => M.li('cal', C.BL, esc(e.title), M.date(e.date) + ' · ' + esc(e.venue), '', 'event.view', e.id)))}</div>`, 'alt') }; });
  M.RES = [['Membership Form (official, blank)', 'MCCI New Membership application form, 4 pages'], ['Temporary membership — how it works', '60 days from fee payment until the permanent certificate is uploaded'], ['Documents checklist by business type', 'Proprietorship, partnership, private and public companies'], ['Certificate of Origin — step by step', 'Guide'], ['Service Guide 2026', 'All seven services']];
  pg('resources', { t: 'Resources', d: 'Downloads: blank official form, checklists, guides' }, () => { EYN = 0; return { title: 'Resources', raw: pageH('Resources', 'Official forms, checklists and guides.') + sec('Downloads', '', `<div class="card" style="max-width:860px;margin:auto">${M.RES.map((r, i) => M.li('file', C.CB, esc(r[0]), esc(r[1]), M.btn('Download', 'res.download', i === 0 ? 'form' : r[0], 'w'))).join('')}</div>`) }; });
  pg('contact', { t: 'Contact', d: 'Contact form and complaint desk (create tickets)' }, () => { EYN = 0; return { title: 'Contact', raw: pageH('Contact & Complaint Desk', 'Reach the Secretariat, or file a complaint with a trackable ticket.') + sec('Get in touch', 'We reply within 24 hours.', `<div class="g2"><div class="card">${M.tabs('ct', ['Contact', 'Complaint desk'], [`<div class="fg"><label>Name<input data-cf="name"></label><label>Mobile / email<input data-cf="contact"></label><label>Subject<input data-cf="subject"></label><label>Member ID (optional)<input data-cf="member"></label><label class="full">Message<textarea data-cf="msg" rows="3"></textarea></label></div><br>${M.btn('Send message', 'contact.send', 'contact', 'p')}`, `<div class="fg"><label>Name<input data-cf="name"></label><label>Complaint about<select data-cf="cat"><option>Service delay</option><option>Staff conduct</option><option>Document issue</option></select></label><label>Token (optional)<input data-cf="member"></label><label class="full">Details<textarea data-cf="msg" rows="3"></textarea></label></div><br>${M.btn('Submit complaint', 'contact.send', 'complaint', 'p')}`])}</div><div class="card"><b>${esc(S().chamber.addr)}</b><p class="muted">Tel ${esc(S().chamber.tel)} · ${esc(S().chamber.email)}<br>Mon–Sat · AI assistant 24/7</p><br><div class="pb">${M.btn('Call', 'help.call', '', '', 'phone')}${M.btn('Email', 'help.email', '', '', 'mail')}${M.btn('Map', 'help.visit', '', '', 'map')}</div></div></div>`) }; });
  pg('login', { t: 'Login', d: 'Member login (password / email code), register (start application), staff login' }, () => ({ title: 'Login', raw: `<div class="lg2"><div><a class="lgo" href="home.html"><img src="${M.base}assets/logo-white.png" style="height:96px" alt="MCCI"></a><h1 style="margin-top:30px">Welcome to the digital Chamber.</h1><p style="max-width:440px">One login for membership, services, documents and payments.</p><p lang="ur" class="ur-line" style="color:#fff">ایک لاگ اِن — رکنیت، خدمات، دستاویزات اور ادائیگیاں</p></div><div>${M.tabs('lg', ['Member login', 'New applicant', 'Staff'], [`<div class="fg" style="grid-template-columns:1fr"><label>Mobile, email or member ID<input value="0300-1234567"></label><label>Password<input type="password" value="demo1234"></label></div><br>${M.btn('Sign in', 'login.member', '', 'p big')} ${M.btn('Sign in with email code', 'login.otp', '', 'big', 'mail')}`, `<p>New to MCCI? Apply on the official form in six simple steps.</p><br>${M.btn('Start membership application', 'register.start', '', 'gold big')}`, `<div class="fg" style="grid-template-columns:1fr"><label>Staff email<input value="ayesha@mcci.org.pk"></label><label>Password<input type="password" value="demo1234"></label></div><br>${M.btn('Open admin panel', 'login.staff', '', 'p big')}`])}</div></div>` }));
